CREATE     PROCEDURE [synapse_fo].[usp_Insert_inventtable]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:51
	Description: Insert stored procedure for INVENTTABLE from synapse finops datalake to BI
*/
