		stg.[FREENOTESGROUP_IT],
		stg.[GROSSDEPTH],
		stg.[GROSSHEIGHT],
		stg.[GROSSWIDTH],
		stg.[HEIGHT],
		stg.[HMIMINDICATOR],
		stg.[HSNCODETABLE_IN],
		stg.[ICMSONSERVICE_BR],
		stg.[INTRASTATCHARGEPERKG],
		stg.[INTRASTATCOMMODITY],
		stg.[INTRASTATEXCLUDE],
		stg.[INTRASTATPROCID_CZ],
