		stg.[INVENTPRODUCTTYPE_BR],
		stg.[ITEMBUYERGROUPID],
		stg.[ITEMDIMCOSTPRICE],
		stg.[ITEMID],
		stg.[ITEMPRICETOLERANCEGROUPID],
		stg.[ITEMTYPE],
		stg.[ITMARRIVALGROUPID],
		stg.[ITMCOMMODITYCODEID],
		stg.[ITMCOSTTRANSFERGROUPID],
		stg.[ITMCOSTTYPEGROUPID],
		stg.[ITMCUSTOMSDESCID],
		stg.[ITMOVERUNDERTOLERANCEGROUPID],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[MARKUPCODE_RU],
		stg.[MATCHINGPOLICY],
		stg.[MINIMUMPALLETQUANTITY],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[NAMEALIAS],
		stg.[NETWEIGHT],
		stg.[NGPCODESTABLE_FR],
		stg.[NONGST_IN],
		stg.[NRTAXGROUP_LV],
		stg.[ORIGCOUNTRYREGIONID],
		stg.[ORIGCOUNTYID],
		stg.[ORIGSTATEID],
		stg.[PACKAGINGGROUPID],
		stg.[PACKING_RU],
		stg.[PARTITION],
		stg.[PDSBASEATTRIBUTEID],
		stg.[PDSBESTBEFORE],
		stg.[PDSCWWMSMINIMUMPALLETQTY],
		stg.[PDSCWWMSQTYPERLAYER],
		stg.[PDSCWWMSSTANDARDPALLETQTY],
		stg.[PDSFREIGHTALLOCATIONGROUPID],
		stg.[PDSITEMREBATEGROUPID],
		stg.[PDSPOTENCYATTRIBRECORDING],
		stg.[PDSSHELFADVICE],
		stg.[PDSSHELFLIFE],
		stg.[PDSTARGETFACTOR],
		stg.[PDSVENDORCHECKITEM],
		stg.[PHANTOM],
		stg.[PKWIUCODE_PL],
		stg.[PMFPLANNINGITEMID],
		stg.[PMFPRODUCTTYPE],
		stg.[PMFYIELDPCT],
		stg.[PRIMARYVENDORID],
		stg.[PRODFLUSHINGPRINCIP],
		stg.[PRODGROUPID],
		stg.[PRODPOOLID],
