		stg.[REQGROUPID],
		stg.[REVRECBUNDLE],
		stg.[REVRECDEFAULTREVENUERECOGNITIONSCHEDULE],
		stg.[REVRECEXCLUDEFROMCARVEOUT],
		stg.[REVRECMEDIANPRICE],
		stg.[REVRECMEDIANPRICEMAXIMUMTOLERANCE],
		stg.[REVRECMEDIANPRICEMINIMUMTOLERANCE],
		stg.[REVRECREVENUERECOGNITIONENABLED],
		stg.[REVRECREVENUETYPE],
		--stg.[RICSISMAINTAINEDEXTERNALLY],
		stg.[SADRATECODE_PL],
		stg.[SALESCONTRIBUTIONRATIO],
		stg.[SALESMODEL],
		stg.[SALESPERCENTMARKUP],
		stg.[SALESPRICEMODELBASIC],
		stg.[SATCODEID_MX],
		stg.[SATTARIFFFRACTION_MX],
		stg.[SCALEINDICATOR_BR],
		stg.[SCRAPCONST],
		stg.[SCRAPVAR],
		stg.[SERIALNUMGROUPID],
		stg.[SERVICEACCOUNTINGCODETABLE_IN],
		stg.[SERVICECODETABLE_IN],
		stg.[SKIPINTRACOMPANYSYNC_RU],
		stg.[SORTCODE],
		stg.[STANDARDCONFIGID],
		stg.[STANDARDINVENTCOLORID],
		stg.[STANDARDINVENTSIZEID],
		stg.[STANDARDINVENTSTYLEID],
		stg.[STANDARDINVENTVERSIONID],
		stg.[STANDARDPALLETQUANTITY],
		stg.[STATISTICSFACTOR],
		--stg.--[SysRowId],
		stg.[TARAWEIGHT],
		stg.[TAXATIONORIGIN_BR],
		stg.[TAXFISCALCLASSIFICATION_BR],
		stg.[TAXPACKAGINGQTY],
		stg.[TAXRATETYPE],
		stg.[TAXSERVICECODE_BR],
		stg.[UNITVOLUME],
		stg.[USEALTITEMID],
		stg.[WIDTH],
		stg.[WMSARRIVALHANDLINGTIME],
		stg.[WMSPALLETTYPEID],
		stg.[WMSPICKINGQTYTIME]	
	FROM [staging_fo].[INVENTTABLE] stg
		LEFT JOIN [synapse_fo].[INVENTTABLE] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[ItemId] = tgt.[ItemId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
	WHERE tgt.[RECID] IS NULL
END
